289	function buildExecutionStageWakeup(input: {
290	  issueId: string;
291	  previousState: ParsedExecutionState | null;
292	  nextState: ParsedExecutionState | null;
293	  interruptedRunId: string | null;
294	  requestedByActorType: "user" | "agent";
295	  requestedByActorId: string;
296	}) {
297	  const { issueId, previousState, nextState, interruptedRunId } = input;
298	  if (!nextState) return null;
299	
300	  if (nextState.status === "pending") {
301	    const agentId =
302	      nextState.currentParticipant?.type === "agent" ? (nextState.currentParticipant.agentId ?? null) : null;
303	    const stageChanged =
304	      previousState?.status !== "pending" ||
305	      previousState?.currentStageId !== nextState.currentStageId ||
306	      !executionPrincipalsEqual(previousState?.currentParticipant ?? null, nextState.currentParticipant ?? null);
307	    if (!agentId || !stageChanged) return null;
308	
309	    const reason =
310	      nextState.currentStageType === "approval" ? "execution_approval_requested" : "execution_review_requested";
311	    const executionStage = buildExecutionStageWakeContext({
312	      state: nextState,
313	      wakeRole: nextState.currentStageType === "approval" ? "approver" : "reviewer",
314	      allowedActions: ["approve", "request_changes"],
315	    });
316	
317	    return {
318	      agentId,
319	      wakeup: {
320	        source: "assignment" as const,
321	        triggerDetail: "system" as const,
322	        reason,
323	        payload: {
324	          issueId,
325	          mutation: "update",
326	          executionStage,
327	          ...(interruptedRunId ? { interruptedRunId } : {}),
328	        },
329	        requestedByActorType: input.requestedByActorType,
