343	  if (nextState.status === "changes_requested") {
344	    const agentId = nextState.returnAssignee?.type === "agent" ? (nextState.returnAssignee.agentId ?? null) : null;
345	    const becameChangesRequested =
346	      previousState?.status !== "changes_requested" ||
347	      previousState?.lastDecisionId !== nextState.lastDecisionId ||
