353	      wakeRole: "executor",
354	      allowedActions: ["address_changes", "resubmit"],
355	    });
356	
357	    return {
358	      agentId,
359	      wakeup: {
360	        source: "assignment" as const,
361	        triggerDetail: "system" as const,
362	        reason: "execution_changes_requested",
